function xlsxXml(string $value): string { return htmlspecialchars($value, ENT_XML1 | ENT_COMPAT, 'UTF-8'); }
function xlsxCol(int $number): string { $out=''; while($number>0){$number--; $out=chr(65+($number%26)).$out; $number=intdiv($number,26);} return $out; }
function xlsxDateValue(?string $value, bool $withTime=false): ?float {
    if(!$value) return null;
    try{$date=new DateTimeImmutable($value,new DateTimeZone('America/Bogota'));$base=new DateTimeImmutable('1899-12-30',new DateTimeZone('America/Bogota'));return ($date->getTimestamp()-$base->getTimestamp())/86400;}catch(Throwable){return null;}
}
function xlsxCell(int $row,int $column,mixed $value,string $type='text'): string {
    $ref=xlsxCol($column).$row; $style=$type==='title'?1:($type==='note'?2:4);
    if($type==='date'||$type==='datetime'){
        $numeric=xlsxDateValue($value,$type==='datetime'); if($numeric!==null)return '<c r="'.$ref.'" s="'.($type==='date'?5:6).'" t="n"><v>'.sprintf('%.8F',$numeric).'</v></c>';
    }
    if($type==='money')$style=7; elseif($type==='number')$style=8;
    elseif($type==='status')$style=$value==='Vencida'?9:($value==='Pagada'?10:11);
    if(($type==='money'||$type==='number')&&is_numeric($value))return '<c r="'.$ref.'" s="'.$style.'" t="n"><v>'.(string)(0+$value).'</v></c>';
    return '<c r="'.$ref.'" s="'.$style.'" t="inlineStr"><is><t xml:space="preserve">'.xlsxXml((string)($value??'')).'</t></is></c>';
}
function xlsxSheet(string $title,string $subtitle,array $headers,array $types,array $rows,array $widths): string {
    $last=xlsxCol(count($headers));$xml='<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetViews><sheetView showGridLines="0" workbookViewId="0"><pane ySplit="4" topLeftCell="A5" activePane="bottomLeft" state="frozen"/></sheetView></sheetViews><sheetFormatPr defaultRowHeight="19"/><cols>';
    foreach($widths as $i=>$width)$xml.='<col min="'.($i+1).'" max="'.($i+1).'" width="'.(float)$width.'" customWidth="1"/>';
    $xml.='</cols><sheetData><row r="1" ht="25" customHeight="1">'.xlsxCell(1,1,$title,'title').'</row><row r="2" ht="20" customHeight="1">'.xlsxCell(2,1,$subtitle,'note').'</row><row r="4" ht="28" customHeight="1">';
    foreach($headers as $i=>$heading)$xml.='<c r="'.xlsxCol($i+1).'4" s="3" t="inlineStr"><is><t>'.xlsxXml((string)$heading).'</t></is></c>';
    $xml.='</row>';
    foreach($rows as $r=>$values){$rowNum=$r+5;$xml.='<row r="'.$rowNum.'">';foreach($values as $i=>$value)$xml.=xlsxCell($rowNum,$i+1,$value,$types[$i]??'text');$xml.='</row>';}
    $lastRow=max(4,count($rows)+4);$xml.='</sheetData><autoFilter ref="A4:'.$last.$lastRow.'"/><mergeCells count="1"><mergeCell ref="A1:'.$last.'1"/></mergeCells><pageMargins left="0.25" right="0.25" top="0.5" bottom="0.5" header="0.2" footer="0.2"/></worksheet>';
    return $xml;
}
